import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"SYNPROXY (scalar SYN gate)","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/detection/synproxy.md","filePath":"openshield-xdp/detection/synproxy.md","lastUpdated":1782795623000}'),n={name:"openshield-xdp/detection/synproxy.md"};function o(l,s,r,p,c,h){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="synproxy-scalar-syn-gate" tabindex="-1">SYNPROXY (scalar SYN gate) <a class="header-anchor" href="#synproxy-scalar-syn-gate" aria-label="Permalink to &quot;SYNPROXY (scalar SYN gate)&quot;">​</a></h1><p>Scalar, rate-based SYN-flood mitigation at XDP — loads on every supported kernel (5.15+) with no per-kernel patching.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li><code>synproxy_check_listener()</code> runs early in the pipeline using <strong>only</strong> pre-parsed scalar fields (<code>is_tcp_syn</code>) — no packet access, no version-specific helpers.</li><li>It accounts each SYN for profiling and returns <code>STAGE_PASS</code> (the baseline never drops here).</li><li>The <strong>rate-limiting stage</strong> tracks per-IP SYN pps. Sources above <code>syn_pps_threshold</code> accrue <code>syn_pps_score</code> and are banned once they cross the suspicion threshold.</li></ol><p>This replaces the older cookie/<code>XDP_TX</code> design, which could fail to verify on some kernels. The scalar gate is portable by construction; richer listener verification is available as an opt-in freplace module on kernel ≥ 6.10.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dynamic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  synproxy_enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # scalar SYN gate (off by default)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  syn_pps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">170</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # per-IP SYN pps before scoring</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  syn_pps_score</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # score added per violation</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Defense in depth</p><p>Also enable the kernel&#39;s own SYN cookies as a complementary second layer: <code>sysctl -w net.ipv4.tcp_syncookies=1</code>.</p></div><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Works for both IPv4 and IPv6 (mitigation rides on <code>ip_stats_map</code> / <code>ip_stats_map_v6</code>).</li><li>Tune <code>syn_pps_threshold</code> to your legitimate per-IP SYN rate; test against your traffic profile before enabling.</li></ul>`,10)])])}const y=e(n,[["render",o]]);export{k as __pageData,y as default};
